// issue #12: 10 行未満・割引率 0.1 → 1,000 × (1 − 0.1) = 900
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

const lines = (n) => Array.from({ length: n }, () => ({ price: 1000, qty: 1 }));

// issue #12: 10 行・小計 10,000・割引率 0.1 → 10,000 × (1 − 0.1) = 9,000、その 5% 引きで 8,550
test('bulk discount is applied once, after the customer discount', () => {
  assert.equal(total(lines(10), 0.1), 8550);
});

// issue #12: 割引率 0 の合計は変えない。まとめ買いは 10 行から（9 行 9,000 のまま、10 行 10,000 の 5% 引きで 9,500）
test('zero discount rate: only the bulk discount applies, from 10 lines', () => {
  assert.equal(total(lines(9), 0), 9000);
  assert.equal(total(lines(10), 0), 9500);
});
